// Standard (C++20 std::popcount)
// Counts the number of 1s (population count).

unsigned int count_set_bits(unsigned int x) {
    // Uses efficient hardware instructions (e.g., POPCNT)
    // C++20 required: #include <bit>
    return std::popcount(x); 
}

// Manual (Brian Kernighan's Algorithm - Clears LSB)
unsigned int popcount_kernighan(unsigned int x) {
    unsigned int count = 0;
    while (x != 0) {
        x &= (x - 1); // Clears the lowest set bit
        count++;
    }
    return count;
}

// Hamming Distance (HD) between two integers:
unsigned int calculate_HD(unsigned int a, unsigned int b) {
    return std::popcount(a ^ b);
}
